tool_input.command:
cat > /tmp/test_csv.js << 'EOF'
import { exportCsv } from './src/export.js';
import { createInvoice, issueInvoice } from './src/invoices.js';

const draft = createInvoice({
  customerId: 'C-001',
  issueDate: '2025-01-15',
  lines: [{ sku: 'DES-HOUR', qty: 10 }],
  terms: 'NET14'
});

if (draft.ok) {
  const inv = issueInvoice(draft.value, []);
  if (inv.ok) {
    const csv = exportCsv([inv.value]);
    console.log(csv);
  }
}
EOF
node /tmp/test_csv.js
